(function () {
'use strict';
// NavegaciÃ³n mÃ³vil
var toggle = document.querySelector('.nav-toggle');
var links = document.querySelector('.nav-links');
if (toggle && links) {
toggle.addEventListener('click', function () {
var open = links.classList.toggle('open');
toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
toggle.setAttribute('aria-label', open ? 'Cerrar menÃº' : 'Abrir menÃº');
});
links.addEventListener('click', function (e) {
if (e.target.tagName === 'A') links.classList.remove('open');
});
}
// AÃ±o dinÃ¡mico en el footer
var year = document.querySelector('[data-year]');
if (year) year.textContent = String(new Date().getFullYear());
// Resaltar enlace de navegaciÃ³n segÃºn secciÃ³n visible
var sections = document.querySelectorAll('section[id]');
var navAnchors = Array.prototype.slice.call(document.querySelectorAll('.nav-links a'));
if ('IntersectionObserver' in window && sections.length) {
var observer = new IntersectionObserver(function (entries) {
entries.forEach(function (entry) {
if (!entry.isIntersecting) return;
navAnchors.forEach(function (a) {
var target = a.getAttribute('href');
if (target === '#' + entry.target.id) {
a.style.background = '#f1f5f9';
a.style.color = '#0f172a';
} else {
a.style.background = 'transparent';
a.style.color = '';
}
});
});
}, { rootMargin: '-40% 0px -55% 0px' });
sections.forEach(function (s) { observer.observe(s); });
}
})();